using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static class InspectSelected {static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;public static object Read(){var g=Selection.activeGameObject;var sv=SceneView.lastActiveSceneView;return new{scene=SceneManager.GetActiveScene().path,selected=g?P(g.transform):null,position=g?g.transform.position.ToString():null,renderers=g?g.GetComponentsInChildren<Renderer>().Select(r=>new{name=r.name,materials=r.sharedMaterials.Select(m=>m?m.name:"NULL").ToArray(),center=r.bounds.center.ToString(),size=r.bounds.size.ToString()}).ToArray():null,viewPosition=sv&&sv.camera?sv.camera.transform.position.ToString():null,viewForward=sv&&sv.camera?sv.camera.transform.forward.ToString():null};}}
